// Automatically calculates a new page each week so you never get duplicate leads
const now = new Date();
const weekNumber = Math.floor(now.getTime() / (7 * 24 * 60 * 60 * 1000));
const page = (weekNumber % 50) + 1;

// Search Apollo for leads — edit these filters to match your target
const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.apollo.io/v1/mixed_people/search',
  headers: {
    'Content-Type': 'application/json',
    'X-Api-Key': # insert key here ,
    'Cache-Control': 'no-cache'
  },
  body: {
    q_keywords: 'angel investor fintech crypto',
    person_titles: ['angel investor', 'investor', 'venture capitalist'],
    person_locations: ['United States'],
    per_page: 10,
    page: page
  },
  json: true
});

const people = response.people || [];

if (people.length === 0) {
  throw new Error('Apollo returned no results for page ' + page + '. Check your API key or search filters.');
}

// Map Apollo fields to clean format — all enrichment comes from Apollo search directly
return people.map(person => {
  const org = person.organization || {};
  const location = [person.city, person.state, person.country].filter(Boolean).join(', ');

  const linkedinRaw = person.linkedin_url || '';
  const linkedin = linkedinRaw
    ? 'https://www.linkedin.com/in/' + linkedinRaw.split('/in/').pop().replace(/\/+$/, '')
    : '';

  const toTitle = s => String(s || '').trim().replace(/\b\w/g, c => c.toUpperCase());

  return {
    json: {
      firstName: person.first_name || '',
      lastName: person.last_name || '',
      name: toTitle((person.first_name || '') + ' ' + (person.last_name || '')),
      investmentGroup: toTitle(org.name || person.organization_name || ''),
      website: org.primary_domain || org.website_url || '',
      title: person.title || '',
      location: location,
      linkedin: linkedin,
      email: person.email || ''
    }
  };
});

const hunterResponse = $input.item.json;
const prevData = $('Apollo Search & Split').item.json;

const data = hunterResponse.data || {};

// Use Apollo email first, fall back to Hunter
const email = prevData.email || data.email || '';

// Use Apollo LinkedIn first, fall back to Hunter
const linkedin = prevData.linkedin ||
  (data.linkedin_url ? ('https://' + data.linkedin_url.replace(/^https?:\/\//, '')) : '') || '';

return [{ json: {
  name: prevData.name,
  firstName: prevData.firstName,
  lastName: prevData.lastName,
  title: prevData.title,
  investmentGroup: prevData.investmentGroup,
  website: prevData.website,
  location: prevData.location,
  linkedin,
  email
} }];

const d = $input.item.json;

// Bing search for LinkedIn if still missing after Apollo + Hunter
let linkedin = d.linkedin || '';
if (!linkedin || !linkedin.includes('linkedin.com/in/')) {
  try {
    const query = encodeURIComponent(d.name + ' ' + d.investmentGroup + ' linkedin.com/in/');
    const searchResult = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://www.bing.com/search?q=' + query,
      headers: { 'User-Agent': 'Mozilla/5.0' }
    });
    const html = typeof searchResult === 'string' ? searchResult : '';
    const matches = html.match(/https?:\/\/(www\.)?linkedin\.com\/in\/[a-zA-Z0-9\-_%]+/g);
    if (matches && matches.length > 0) {
      linkedin = matches[0].split('?')[0];
      if (!linkedin.startsWith('https://www.')) {
        linkedin = 'https://www.linkedin.com/in/' + linkedin.split('/in/')[1];
      }
    }
  } catch (e) {
    console.log('Bing search error:', e.message);
  }
}

// Claude AI enrichment and scoring
const prompt = 'Based on your training knowledge, provide information about this angel investor: ' + d.name + ', title ' + d.title + ', associated with ' + d.investmentGroup + '. LinkedIn: ' + (linkedin || 'none') + '. Return ONLY a valid JSON object with exactly these fields: correctedTitle (their actual title - if they are purely an angel investor with no institutional role use Angel Investor - if they are an angel investor AND have an institutional role combine both like Angel Investor and Partner at Their Firm - if you cannot confirm angel investing activity use their known professional title), confirmedAngel (true if they do personal angel investing individually or via syndicate, false only if zero personal investing activity), fundSize (known AUM or personal fund size as a string or empty string), avgCheckSize (typical angel check size range as a string or empty string), stageFocus (investment stages they focus on), sectorFocus (sectors they invest in), recentActivity (Yes or No based on whether they have been actively investing in the last 1-2 years), reachable (false if this person likely has over 10000 LinkedIn followers - true only if they likely have under 10000 LinkedIn followers and are accessible to cold outreach from unknown founders), fitScore (exactly Tier 1 or Tier 2 for fit with a pre-seed fintech consumer or crypto startup in California - Tier 1 means they have angel investing or personal investing in their LinkedIn title AND have blockchain or crypto or fintech investment history AND are under 10000 followers - Tier 2 means they angel invest but may not have explicit fintech or crypto focus), note (one sentence summarizing their investing focus and how well they fit a pre-seed fintech consumer or crypto startup - be honest about whether they are a good fit or not). No markdown no code blocks just raw JSON.';

const result = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.anthropic.com/v1/messages',
  headers: {
    'x-api-key': '#input api key here',
    'anthropic-version': '2023-06-01',
    'Content-Type': 'application/json'
  },
  body: {
    model: 'claude-sonnet-4-20250514',
    max_tokens: 1000,
    messages: [{ role: 'user', content: prompt }]
  },
  json: true
});

let enriched = {
  correctedTitle: '',
  confirmedAngel: false,
  fundSize: '',
  avgCheckSize: '',
  stageFocus: '',
  sectorFocus: '',
  recentActivity: '',
  fitScore: '',
  note: '',
  reachable: false
};

try {
  const contentBlocks = result.content || [];
  let text = '';
  for (const block of contentBlocks) {
    if (block.type === 'text') { text = block.text; }
  }
  if (text) {
    const stripped = text.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
    enriched = JSON.parse(stripped);
  }
} catch (e) {
  console.log('Claude parse error:', e.message);
}

const toStr = v => Array.isArray(v) ? v.join(', ') : (v || '');
const title = toStr(enriched.correctedTitle) || d.title;

return [{
  json: {
    name: d.name,
    title: title,
    investmentGroup: d.investmentGroup,
    website: d.website,
    location: d.location,
    linkedin: linkedin,
    email: d.email,
    fundSize: toStr(enriched.fundSize),
    avgCheckSize: toStr(enriched.avgCheckSize),
    stageFocus: toStr(enriched.stageFocus),
    sectorFocus: toStr(enriched.sectorFocus),
    recentActivity: toStr(enriched.recentActivity),
    fitScore: toStr(enriched.fitScore),
    note: toStr(enriched.note),
    reachable: enriched.reachable === true || String(enriched.reachable).toLowerCase() === 'true'
  }
}];

const d = $input.item.json;

const hasName = (d.name || '').trim().length > 0;
const hasInvestmentGroup = typeof d.investmentGroup === 'string' && d.investmentGroup.trim().length > 0;
const hasLinkedin = typeof d.linkedin === 'string' && d.linkedin.trim().length > 0;
const hasEmail = typeof d.email === 'string' && d.email.trim().length > 0;

if (!hasName || !hasInvestmentGroup || !hasLinkedin || !hasEmail) {
  return [];
}

return [{ json: {
  ...d,
  fitScore: d.fitScore || 'Unscored',
  fundSize: d.fundSize || '',
  avgCheckSize: d.avgCheckSize || '',
  stageFocus: d.stageFocus || '',
  sectorFocus: d.sectorFocus || '',
  recentActivity: d.recentActivity || '',
  note: d.note || ''
} }];
